form.script:
// Check if user has POS permissions and redirect accordingly
function checkPOSRedirect() {
    // Check if current user has POS permissions
    // We'll use an RPC call to check user's groups
    if (typeof session !== 'undefined' && session.uid) {
        // Make an RPC call to check user's group membership
        fetch('/web/dataset/call_kw', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {
                    model: 'res.users',
                    method: 'read',
                    args: [[session.uid], ['groups_id']],
                    kwargs: {}
                },
                id: Date.now()
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.result && data.result[0]) {
                const userGroups = data.result[0].groups_id;
                // Check if user has POS user or POS manager permissions
                // These are typically the IDs of the groups
                // - POS User: point_of_sale.group_pos_user
                // - POS Manager: point_of_sale.group_pos_manager

                // For now, we'll redirect to POS page
                // In a complete implementation, we'd check the group IDs
                window.location.href = '/pos/ui';
            }
        })
        .catch(error => {
            console.error('Error checking user permissions:', error);
        });
    }
}

// Add a check to see if we just logged in from the cashier login page
if (window.location.pathname === '/web' && document.referrer && document.referrer.includes('/cashier/login')) {
    // User came from cashier login, so let's check their permissions and redirect if needed
    setTimeout(checkPOSRedirect, 1000); // Wait a bit for session to be initialized
}
